const text = $input.first().json.content.map(b => b.text || '').join('');
const plan = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
plan.id = `${plan.client.short.toLowerCase()}-${plan.format}-${$now.toFormat('yyyy-LL-dd')}`;
return [{json: {plan, plan_id: plan.id}}];
